import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import { Camera, Route as RouteIcon } from 'lucide-react';
import { PageHeader } from '@/components/common/PageHeader';
import { EntityCard } from '@/components/common/EntityCard';
import { ReviewStatusBadge } from '@/components/common/StatusBadge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/controls';
import { SkeletonList } from '@/components/ui/skeleton';
import { EmptyState, ErrorState } from '@/components/feedback/states';
import { formatDateTime, formatDistance, formatPercent } from '@/lib/format';
import { useActiveDepot, useAuth } from '@/features/auth/session';
import { useTrips } from './api';

export default function TripsPage() {
  const { t } = useTranslation();
  const { can } = useAuth();
  const depot = useActiveDepot();
  const [tab, setTab] = useState('today');

  const today = new Date().toISOString().slice(0, 10);
  const todayReadings = useTrips({ depotId: depot?.id ?? null, from: today, limit: 100 });
  const recent = useTrips({ depotId: depot?.id ?? null, limit: 40 });

  const list = tab === 'today' ? todayReadings : recent;

  return (
    <div className="space-y-4">
      <PageHeader
        title={t('trips.title')}
        description={depot?.name}
        action={
          can('trip.create') && (
            <Button asChild size="md">
              <Link to="/trips/add">
                <Camera className="size-4" aria-hidden />
                {t('home.addBusDetails')}
              </Link>
            </Button>
          )
        }
      />

      <Tabs value={tab} onValueChange={setTab}>
        <TabsList>
          <TabsTrigger value="today">{t('trips.today')}</TabsTrigger>
          <TabsTrigger value="recent">{t('trips.recent')}</TabsTrigger>
        </TabsList>

        <TabsContent value={tab} className="space-y-3">
          {list.isLoading && <SkeletonList count={3} />}
          {list.isError && <ErrorState error={list.error} onRetry={() => void list.refetch()} />}
          {!list.isLoading && (list.data?.length ?? 0) === 0 && (
            <EmptyState
              icon={RouteIcon}
              title={t('empty.trips')}
              description={t('empty.tripsBody')}
              action={
                can('trip.create') && (
                  <Button asChild>
                    <Link to="/trips/add">{t('home.addBusDetails')}</Link>
                  </Button>
                )
              }
            />
          )}
          <ul className="space-y-3">
            {list.data?.map((trip) => (
              <li key={trip.id}>
                <EntityCard
                  to={`/trips/${trip.id}`}
                  icon={RouteIcon}
                  title={trip.bus?.registration_number ?? ''}
                  subtitle={`${trip.route?.name ?? ''} · ${formatDateTime(trip.captured_at)}`}
                  meta={
                    <>
                      <ReviewStatusBadge status={trip.review_status} />
                      {trip.calculated_distance_km != null && (
                        <span className="tabular text-xs text-muted-foreground">
                          {t('units.kmValue', {
                            value: formatDistance(trip.calculated_distance_km),
                          })}
                        </span>
                      )}
                      {trip.distance_variance_pct != null && (
                        <span className="tabular text-xs text-muted-foreground">
                          {formatPercent(trip.distance_variance_pct, { signed: true })}
                        </span>
                      )}
                    </>
                  }
                />
              </li>
            ))}
          </ul>
        </TabsContent>
      </Tabs>
    </div>
  );
}
